#include <chrono>
int main(){using namespace nexweave::protocol;ControlRequest r;r.request_id="req-1";r.operation="start";r.work_id="w-1";r.session_id="s-1";r.generation=2;r.deadline=std::chrono::milliseconds(100);auto e=encode_request(r);if(!e.ok())return 1;auto d=decode_request(*e.value);if(!d.ok()||d.value->generation!=2)return 2;if(decode_request("{\"version\":1}").ok())return 3;r.deadline=std::chrono::milliseconds(0);if(validate_request(r).ok())return 4;ControlResponse p;p.request_id="req-1";p.result=nexweave::domain::OperationResult::failure(nexweave::domain::ErrorCode::kAlreadyCompleted,"重复请求");p.replayed=true;auto pe=encode_response(p);if(!pe.ok())return 5;auto pd=decode_response(*pe.value);if(!pd.ok()||!pd.value->replayed)return 6;return 0;}
